config.script:

lotStateReasonAssetLinkId = self.props.data.getValueAt(event.row, 'lotStateReasonAssetLinkId')
if self.view.custom.security.action.canUpdate:
	if event.column == 'enabled':	
		retVal =system.kanoa.asset.lotStateReasonAssetLinkId(lotStateReasonAssetLinkId, event.value)
		if retVal > 0: 
			system.perspective.sendMessage('showSuccessfulToast', {'message': 'link updated'})
		else:
			system.perspective.sendMessage('showFailerToast', {'message': 'link was not updated'})
	else: system.perspective.sendMessage('showFailerToast', 'Column is not enabled for editing.')
	self.view.refreshBinding("custom.assetStates.data")
else: system.perspective.sendMessage('showFailerToast', 'No permissions to update states.')

return

if self.view.custom.itemStates.userAction.canUpdate:
	itemStateId = self.props.data.getValueAt(event.row, 'itemStateId')

	if event.column in ('enabled', 'itemStateName'):
		retVal, msg = system.kanoa.item.updateItemStateField(itemStateId, event.column, event.value, self.view.custom.security.userId)			
		if msg: system.perspective.sendMessage('showFailerToast', {'message': 'Failed to update the item state. %s'%msg})
		else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Item State has been updated'})		
	else:
		system.perspective.sendMessage('showFailerToast', 'Column is not enabled for editing')
else:
	system.perspective.sendMessage('showFailerToast', 'No permissions to update item states')

self.view.refreshBinding("custom.itemStates.data")
self.view.refreshBinding("custom.itemStates.filteredData")
self.props.selection.selectedRow = None	
self.props.selection.selectedCol = None	

return

customMethods.script:

for row in self.view.custom.itemStates.selectedData:
	retVal, response = system.kanoa.item.deleteItemState(row['itemStateId'], self.view.custom.security.userId)
	if response == 'Disabled': system.perspective.sendMessage('showWarningToast', {'message': 'Item state %s has been disabled as there are historical entries asssociated with this item state'%row['itemStateName']})
	else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Item state %s has been deleted'%row['itemStateName']})

self.view.refreshBinding("custom.itemStates.data")
self.view.refreshBinding("custom.itemStates.filteredData")

return

