	system.perspective.print("updatePopupSelection msg received with %s"%payload)

	if payload['msgHandler'] == 'itemStateClassSelected': 
		if len(payload['selection']) > 0: selection = payload['selection'][0]['value']
		else:
			selection = {
						"changedBy": None,
						"changedDate": None,
						"createdBy": None,
						"createdDate": None,
						"enabled": True,
						"itemStateClassDescription": None,
						"itemStateClassId": None,
						"itemStateClassName": None,
						"itemStateClassPath": None,
						"label": None,
						"parentId": None,
						"path": None,
						"treeLevel": None
						}

		self.view.custom.itemStateClass.selected = selection

	elif payload['msgHandler'] == 'itemSelected':
 		items = []
 		for item in payload['selection']:
 			if item['value'].has_key('itemId'): items.append({'itemId': item['value']['itemId']})
 			elif item['value'].has_key('path'): 
 				itemClassId = system.kanoa.utilities.getFieldValue('itemClassId', system.kanoa.item.getItemClasses({'itemClassPath': item['value']['path']}))
 				items.append({'itemClassId': itemClassId})
		self.view.custom.userSelection.itemInfo = items
	elif payload['msgHandler'] == 'assetSelected':
		self.view.custom.userSelection.assetInfo = [{'assetId': item['value']['assetId']} for item in payload['selection']]
	elif payload['msgHandler'] == 'itemStateSelected':
 		items = []
 		for item in payload['selection']:
 			if item['value'].has_key('itemStateId'): items.append({'itemStateId': item['value']['itemStateId']})
 			elif item['value'].has_key('path'): 
 				system.perspective.print("fff")
